{
  "bioavailability_prediction": "high",
  "claims": [
    {
      "card_ids": ["C50"],
      "claim": "Hydrocortisone, a corticosteroid sharing the same steroidal enone/polyol core, had an absolute oral bioavailability of 95.9% in eight subjects, directly supporting high F for the query's steroid scaffold.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C10"],
      "claim": "Prednisolone tablets showed F=0.97 in normal subjects, indicating near-complete oral absorption of a corticosteroid with multiple hydroxyl groups.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C03"],
      "claim": "Methylprednisolone oral solution delivered 72.6% of the dose to the systemic circulation relative to IV, showing high oral bioavailability for a close corticosteroid analogue.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C05"],
      "claim": "Digitoxin, a cardiac glycoside with high molecular weight and many H-bond donors, had 91.2% absolute oral bioavailability, demonstrating that high polarity/HBD does not preclude F≥20%.",
      "evidence_role": "supportive"
    },
    {
      "card_ids": ["C41"],
      "claim": "Glycyrrhizin had only ~0.25% oral bioavailability, but as a triterpenoid saponin glycoside with two glucuronic acids it is structurally distant from the neutral hexahydroxy steroid query and carries low transferability.",
      "evidence_role": "contradictory"
    }
  ],
  "confidence": "moderate",
  "decision_summary": "The query is a polyhydroxylated neutral steroid. The most transferable experimental evidence comes from corticosteroid analogues (hydrocortisone, prednisolone, methylprednisolone) and cardiac glycosides (digitoxin), all showing high oral bioavailability (72–96%) despite multiple H-bond donors and high TPSA. The low-F examples (glycyrrhizin) are structurally distant and carry little weight. Although the query's six hydroxyls may reduce permeability, the 20% threshold is low and the steroid scaffold is generally well absorbed; therefore F≥20% is better supported.",
  "evidence_gaps": [
    "No direct experimental oral bioavailability data for the query molecule.",
    "No analogue with the exact hexahydroxy substitution pattern is available.",
    "Uncertainty remains about intestinal permeability and first-pass metabolism of this specific polyhydroxylated steroid."
  ],
  "new_evidence_assessment": [],
  "revision_action": "initial"
}

